// Public executed-test copy: synthetic role email redacted where present.
import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func testChatKeyboardAfterReopenAndAncestorNoticeDisappears() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Inbox, tab, 4 of 5");let group=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA fixed notifications table")).firstMatch;XCTAssertTrue(group.waitForExistence(timeout:12),app.debugDescription);group.tap();let msg=app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch;XCTAssertTrue(msg.waitForExistence(timeout:12));type(msg,"QA100");XCTAssertEqual(msg.value as? String,"QA100");let keyboard=app.keyboards.firstMatch,send=app.buttons["Send"];XCTAssertTrue(keyboard.waitForExistence(timeout:10));XCTAssertTrue(send.isHittable);XCTAssertLessThanOrEqual(send.frame.maxY,keyboard.frame.minY+1);let decline=app.buttons["Decline analytics"];XCTAssertTrue(decline.exists,app.debugDescription);XCTAssertTrue(decline.isHittable);decline.tap();XCTAssertTrue(keyboard.exists);let reachable=XCTNSPredicateExpectation(predicate:NSPredicate(format:"hittable == true"),object:send);XCTAssertEqual(XCTWaiter.wait(for:[reachable],timeout:10),.completed);XCTAssertLessThanOrEqual(send.frame.maxY,keyboard.frame.minY+1);print("QA_NATIVE100_AFTER_ANCESTOR_CHANGE keyboard=\(keyboard.frame) input=\(msg.frame) send=\(send.frame) hittable=\(send.isHittable)\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native100-reopen-keyboard-notice-dismissed";a.lifetime = .keepAlways;add(a);send.tap();XCTAssertTrue(app.staticTexts["QA100"].waitForExistence(timeout:15),app.debugDescription)
 }
}
